import{_ as t,o as i,c as a,a2 as n}from"./chunks/framework.CD2m2Tvf.js";const u=JSON.parse('{"title":"Project Pitch: Distributed Tracing & Observability Platform","description":"","frontmatter":{},"headers":[],"relativePath":"00b-project-pitch.md","filePath":"00b-project-pitch.md"}'),r={name:"00b-project-pitch.md"};function o(s,e,c,l,d,p){return i(),a("div",null,[...e[0]||(e[0]=[n('<h1 id="project-pitch-distributed-tracing-observability-platform" tabindex="-1">Project Pitch: Distributed Tracing &amp; Observability Platform <a class="header-anchor" href="#project-pitch-distributed-tracing-observability-platform" aria-label="Permalink to &quot;Project Pitch: Distributed Tracing &amp; Observability Platform&quot;">​</a></h1><h2 id="_30-second-elevator-pitch" tabindex="-1">30-Second Elevator Pitch <a class="header-anchor" href="#_30-second-elevator-pitch" aria-label="Permalink to &quot;30-Second Elevator Pitch&quot;">​</a></h2><blockquote><p>&quot;I built a high-throughput, OpenTelemetry-compatible distributed tracing backend and interactive observability dashboard. The backend ingests OTLP span batches via FastAPI with non-blocking tail-sampling and stream processing, persisting billions of spans into an append-only columnar database. On top of this data pipeline, I built an ML anomaly detection engine that isolates latency regressions and uses a pre-trained LLM to summarize incident root causes, alongside a React waterfall timeline that calculates the distributed critical path in real time.&quot;</p></blockquote><hr><h2 id="_2-minute-technical-interview-pitch" tabindex="-1">2-Minute Technical Interview Pitch <a class="header-anchor" href="#_2-minute-technical-interview-pitch" aria-label="Permalink to &quot;2-Minute Technical Interview Pitch&quot;">​</a></h2><blockquote><p>&quot;In modern microservice architectures, diagnosing distributed latency regressions is notoriously difficult because requests fan out across dozens of asynchronous services. Traditional metrics tell you <em>that</em> something is slow, but they don&#39;t tell you <em>where</em> or <em>why</em>.</p><p>To solve this, I designed and implemented <strong>14-Tracing-Backend</strong>, a full-stack distributed tracing and incident intelligence platform.</p><p>On the ingestion side, the backend exposes OpenTelemetry-compliant OTLP endpoints in FastAPI. Ingestion is decoupled from storage through an in-memory queue and ring buffer that applies adaptive sampling. Instead of blindly sampling 1% of traffic at the gateway, I implemented tail-based sampling: 100% of errors and high-latency p99 traces are retained, while boring, uniform 200 OK spans are dynamically downsampled, reducing storage costs by over 75% without losing anomaly visibility.</p><p>For trace assembly, the backend dynamically reconstructs the Directed Acyclic Graph of spans using parent-child span IDs, resolving clock skews and computing the critical execution path—the exact sequence of dependent operations that dictated total user response time.</p><p>In the data intelligence layer, I implemented eleven specialized ML modules covering latency outlier detection, dependency topology shifts, and causal graph root-cause analysis. For incident response, an automated pipeline queries a pre-trained LLM via API to generate natural-language incident postmortems complete with offending span attributes and remediation suggestions.</p><p>The frontend is built in React 18, TypeScript, and Vite, featuring an interactive waterfall Gantt chart, hierarchical span tree, and dependency graph. The test suite includes 313 unit and integration tests passing across Python and TypeScript, ensuring rock-solid stability.&quot;</p></blockquote>',6)])])}const m=t(r,[["render",o]]);export{u as __pageData,m as default};
